.PHONY: help install train test serve docker-build docker-run clean lint format

help:
	@echo "Available commands:"
	@echo "  make install       - Install dependencies"
	@echo "  make train         - Train the model"
	@echo "  make test          - Run tests"
	@echo "  make serve         - Start API server"
	@echo "  make docker-build  - Build Docker image"
	@echo "  make docker-run    - Run Docker container"
	@echo "  make clean         - Clean generated files"
	@echo "  make lint          - Run linting"
	@echo "  make format        - Format code"

install:
	@echo "Installing dependencies..."
	pip install -r requirements.txt

train:
	@echo "Training model..."
	python src/sample_model.py

test:
	@echo "Running tests..."
	pytest tests/ -v --cov=src --cov-report=html --cov-report=term

serve:
	@echo "Starting API server..."
	uvicorn src.app:app --reload --host 0.0.0.0 --port 8000

docker-build:
	@echo "Building Docker image..."
	docker build -t mlops-model:latest .

docker-run:
	@echo "Running Docker container..."
	docker run -p 8000:8000 mlops-model:latest

clean:
	@echo "Cleaning generated files..."
	rm -rf __pycache__ .pytest_cache .coverage htmlcov
	rm -f model.pkl
	find . -type d -name "__pycache__" -exec rm -rf {} +
	find . -type f -name "*.pyc" -delete

lint:
	@echo "Running linting..."
	flake8 src/ tests/ --max-line-length=100 --ignore=E501,W503

format:
	@echo "Formatting code..."
	black src/ tests/
	isort src/ tests/

mlflow-ui:
	@echo "Starting MLflow UI..."
	mlflow ui --port 5000

dvc-status:
	@echo "Checking DVC status..."
	dvc status

dvc-push:
	@echo "Pushing data to DVC remote..."
	dvc push

dvc-pull:
	@echo "Pulling data from DVC remote..."
	dvc pull

"""
FastAPI server for model inference
Install: pip install fastapi uvicorn
Run: uvicorn app:app --reload
"""
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
import joblib
import numpy as np
from pathlib import Path
from typing import List

app = FastAPI(title="ML Model API", version="1.0.0")

# Load model at startup
MODEL_PATH = "model.pkl"
model = None


@app.on_event("startup")
async def load_model():
    """Load model when API starts"""
    global model
    if Path(MODEL_PATH).exists():
        model = joblib.load(MODEL_PATH)
        print(f"Model loaded from {MODEL_PATH}")
    else:
        print(f"Warning: Model file {MODEL_PATH} not found")


class PredictionInput(BaseModel):
    """Input data schema"""
    features: List[float]


class PredictionOutput(BaseModel):
    """Output prediction schema"""
    prediction: float
    model_version: str = "1.0.0"


@app.get("/")
async def root():
    """Health check endpoint"""
    return {
        "status": "healthy",
        "model_loaded": model is not None,
        "version": "1.0.0"
    }


@app.get("/health")
async def health():
    """Detailed health check"""
    return {
        "status": "healthy" if model is not None else "model_not_loaded",
        "model_path": MODEL_PATH,
        "model_exists": Path(MODEL_PATH).exists()
    }


@app.post("/predict", response_model=PredictionOutput)
async def predict(input_data: PredictionInput):
    """Make prediction"""
    if model is None:
        raise HTTPException(status_code=503, detail="Model not loaded")

    try:
        # Convert input to numpy array
        features = np.array([input_data.features])

        # Make prediction
        prediction = model.predict(features)[0]

        return PredictionOutput(
            prediction=float(prediction),
            model_version="1.0.0"
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/predict/batch")
async def predict_batch(inputs: List[PredictionInput]):
    """Batch prediction endpoint"""
    if model is None:
        raise HTTPException(status_code=503, detail="Model not loaded")

    try:
        features = np.array([inp.features for inp in inputs])
        predictions = model.predict(features)

        return {
            "predictions": predictions.tolist(),
            "count": len(predictions)
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
